'use strict';
const LifeGrowth=(()=>{
const stages=[{min:0,name:'ทารก'},{min:2,name:'เด็กเล็ก'},{min:6,name:'วัยเรียน'},{min:13,name:'วัยรุ่น'},{min:18,name:'ผู้ใหญ่'},{min:40,name:'วัยกลางคน'},{min:65,name:'วัยสูงอายุ'}];
const educationLabels={home:'เรียนรู้ในบ้าน',community:'โรงเรียนชุมชน',apprentice:'ฝึกงานกับช่าง',academy:'สถาบันวิชา',self:'เรียนรู้ด้วยตนเอง'};
const bio=s=>Engine.biological(s);
function stage(s){const age=bio(s);const base=stages.filter(x=>age>=x.min).slice(-1)[0];return typeof Ecology!=='undefined'&&s.race!==0?{...base,name:Ecology.stage(s,base.min)}:base}
function ensure(s){if(!s.growth){const age=bio(s);s.growth={version:1,lastAge:age,stage:stage(s).name,education:s.race!==0&&typeof SpeciesSociety!=='undefined'?SpeciesSociety.education(s,age):age<6?'home':s.flags.academy?'academy':age<13?'community':s.rank>=4?'academy':'self',milestones:stages.filter(x=>x.min<=age).map(x=>x.min),lastQuarter:-1}}return s.growth}
function choose(s,education){if(!Object.hasOwn(educationLabels,education)||bio(s)<6||s.dead)return false;ensure(s).education=education;return true}
function quarter(s){const g=ensure(s),age=bio(s),now=s.calendar?.count??0;if(g.lastQuarter===now)return null;g.lastQuarter=now;const pace=85/RACES[s.race][2];if(age>=2&&age<18)s.power=Math.min(100,s.power+.3*pace);if(age>=6&&age<20){s.wisdom=Math.min(100,s.wisdom+.15*pace);if(g.education==='academy')s.magic=Math.min(100,s.magic+.18*pace);if(g.education==='apprentice')s.power=Math.min(100,s.power+.15*pace)}if(age>=65)s.power=Math.max(0,s.power-.03*pace);const previous=g.stage,current=stage(s);g.stage=current.name;g.lastAge=age;let entry=null;
for(const point of stages){if(age>=point.min&&!g.milestones.includes(point.min)){g.milestones.push(point.min);const relative=FamilyWorld.list(s).find(m=>m.alive),person=relative?relative.name:'คนที่รู้จักคุณ';const lines={2:['ก้าวเล็ก ๆ ที่เริ่มไปได้เอง',`${person}ขยับเก้าอี้ออกจากทาง คุณประคองตัวจากขอบโต๊ะแล้วลองเดินโดยไม่เกาะอะไร ระยะทางสั้น ๆ วันนี้ทำให้ห้องเดิมดูกว้างขึ้น`,'เสียง คำ และกลิ่นคุ้นเคยเริ่มเชื่อมกันเป็นสิ่งที่คุณจำได้ คุณยังต้องพักบ่อยและมีคนคอยดูแลใกล้ ๆ'],6:['เส้นทางไปเรียนวันแรก',`${person}ช่วยเตรียมของใช้สำหรับการเรียน คุณลองบอกชื่อและนามสกุลให้ครูฟัง ก่อนหาที่นั่งใกล้คนที่ยังอ่านช้าเหมือนกัน`,'ฐานะของบ้านกำหนดว่าคุณมีเวลาฝึกและหนังสือเท่าไร แต่การเรียนรู้ยังเกิดได้ทั้งในห้องเรียน ร้านช่าง และที่บ้าน'],13:['งานที่เริ่มรับผิดชอบเอง',`คุณจัดเวลาระหว่างการเรียนกับงานเล็ก ๆ ในบ้าน ใน${KINGDOMS[s.kingdom][0]} เส้นทางฝึกช่าง เรียนวิชา และทำงานรับจ้างมีค่าใช้จ่ายและโอกาสต่างกัน`,'คุณเริ่มเลือกว่าจะฝึกอะไรต่อ การตัดสินใจเรื่องการศึกษาจะเปลี่ยนพื้นฐานของงานที่ทำได้ในภายหลัง'],18:['กุญแจและความรับผิดชอบ',s.job!==null?`คุณทำงานเป็น${JOBS[s.job][0]}แล้ว เริ่มนับรายได้กับค่าใช้จ่ายด้วยตนเอง ชื่อบนสมุดงานเป็นชื่อเดียวกับที่ครอบครัวเคยเรียกในวัยเด็ก`:'คุณเริ่มจัดงบสำหรับอาหาร ที่พัก และการฝึกวิชา ช่วงนี้ยังไม่มีงานประจำ จึงสำรวจเส้นทางที่คุณมีทักษะพอจะเริ่มได้','รูปร่างและจังหวะชีวิตต่างจากวัยเรียน คุณมีแรงพอจะลองหลายอย่าง แต่เวลากับคนใกล้ตัวต้องจัดไว้ให้ด้วย'],40:['ความชำนาญและสิ่งที่เริ่มต้องพัก',s.job!==null?`ในงาน${JOBS[s.job][0]} คุณเริ่มแยกเรื่องเร่งด่วนกับเรื่องที่รอได้ ประสบการณ์ช่วยให้ทำงานแม่นขึ้น แต่คุณก็ต้องพักมือและสายตาเป็นช่วง ๆ`:'คุณมองงานและความสัมพันธ์ด้วยประสบการณ์มากขึ้น เรื่องที่เคยรีบตอบเริ่มมีรายละเอียดให้ฟังก่อนตัดสินใจ','คนใกล้ตัวต่างมีภาระของตนเอง การรักษาความสัมพันธ์จึงต้องอาศัยการนัดหมายและการช่วยกันจริง ๆ'],65:['จัดชีวิตให้เข้ากับร่างกายในวันนี้','คุณย้ายของที่ใช้บ่อยมาไว้ระดับหยิบถึง และเว้นเวลาพักระหว่างงาน ความรู้ยังอยู่ครบ แต่ร่างกายต้องการจังหวะที่ช้าลง','คุณเลือกทำงานต่อได้ หรือค่อย ๆ ลดงานและส่งต่อวิชาให้คนรุ่นหลัง ชีวิตช่วงนี้มีทางเลือกของมันเช่นเดียวกับทุกวัย']};if(lines[point.min]){const a=lines[point.min];entry={title:a[0],paragraphs:a.slice(1),kind:'growth',key:'growth-'+point.min};if(point.min===6&&g.education==='home')g.education='community'}}}
if(entry&&typeof BirthEras!=='undefined')entry=BirthEras.growth(s,entry);if(entry&&typeof Ecology!=='undefined'&&s.race!==0)entry=Ecology.growth(s,Number(entry.key.slice(7)),FamilyWorld.list(s).find(m=>m.alive)?.name||'ผู้ดูแลถิ่น')||entry;return entry}
function valid(s){const g=s.growth;if(!g)return true;return g.version===1&&Number.isFinite(g.lastAge)&&g.lastAge>=0&&g.lastAge<20000&&(stages.some(x=>x.name===g.stage)||typeof Ecology!=='undefined'&&stages.some(x=>Ecology.stage(s,x.min)===g.stage))&&Object.hasOwn(educationLabels,g.education)&&Array.isArray(g.milestones)&&g.milestones.length<=7&&g.milestones.every(x=>stages.some(t=>t.min===x))&&Number.isInteger(g.lastQuarter)&&g.lastQuarter>=-1&&g.lastQuarter<20000}
const educationLabel=(s,key=ensure(s).education)=>(typeof BirthEras!=='undefined'&&BirthEras.learningLabel(s,key))||(typeof Ecology==='undefined'?educationLabels[key]:Ecology.learningLabel(s,key));
return {educationLabel,ensure,quarter,stage,bio,choose,valid,stages,educationLabels};
})();
